Object.assign(dict.en,{"adminLogin": "Administrator sign-in", "adminLoginBody": "Manage the catalogue, orders and shipments. Administrator access only.", "adminSpace": "BOOKSHOP WORKSPACE", "viewShop": "Visit the shop", "invalid_admin_credentials": "Check your administrator email and password. Customer accounts cannot access this area.", "adminSearch": "Order number, name or phone", "allStatuses": "All statuses", "noMatchingOrders": "No orders match these filters.", "trackingNumber": "Nova Poshta tracking number", "trackingHint": "Enter the 14 digits from the label you created with the carrier.", "saveShipment": "Save tracking number and dispatch", "updateShipment": "Update tracking number", "trackParcel": "Track on Nova Poshta’s website", "invalid_tracking": "The tracking number must contain 14 digits.", "tracking_required": "Add a tracking number before dispatch.", "shipmentSaved": "Tracking number saved and visible in the customer account.", "moreWarehouses": "Load more collection points", "retryShipping": "Retry search", "warehouseLoading": "Finding collection points…", "selectedDestination": "Your collection point", "branch": "Branch", "locker": "Parcel locker", "openingHours": "Opening hours", "shippingReview": "Choose a city and collection point from the results first.", "phoneHint": "Ukrainian number, e.g. +380501234567", "invalid_phone": "Enter a Ukrainian number: +380 and 9 digits, or 0 and 9 digits.", "warehouseHint": "Search by number or street. Load more collection points with the button below.", "deliveryTariff": "Delivery and cash-on-delivery fees are charged separately at the carrier’s rates. The website total covers books only. The seller creates the shipping label after confirmation.", "orderTrackingBody": "After dispatch, the tracking number appears in your account. Open Nova Poshta’s website and enter this number to track the parcel.", "Mon": "Mon", "Tue": "Tue", "Wed": "Wed", "Thu": "Thu", "Fri": "Fri", "Sat": "Sat", "Sun": "Sun"});
const pageName=document.querySelector("main")?.dataset.page||"home";
let currentPage=1,shipping={city:null,cities:[],warehouses:[],selected:null,page:0,hasMore:false,query:''},shippingRequest=0,cityRequest=0,checkoutDraft={},adminStatus='all',adminQuery='';
const t=k=>dict[lang][k]||k, local=(b,k)=>b[k+(lang==='uk'?'Uk':'En')], money=v=>new Intl.NumberFormat(lang==='uk'?'uk-UA':'en-GB',{style:'currency',currency:'UAH',maximumFractionDigits:v%100?2:0}).format(v/100);
function persist(){localStorage.setItem('cherry-cart',JSON.stringify(cart));$('#cart-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
async function api(path,method='GET',data){const r=await fetch('/api'+path,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let value;try{value=await r.json()}catch{value={}}if(!r.ok){const e=new Error(r.status===429?t('rateLimit'):t(value.error||'errorGeneric'));e.code=value.error;e.status=r.status;throw e}return value}
function translate(){document.documentElement.lang=lang;document.documentElement.dataset.theme=theme;document.title='Cherry Books — '+t(({home:'findBook',catalog:'catalog',about:'aboutPage',contacts:'contacts',delivery:'deliveryPage',faq:'faq',login:'login',register:'registration',account:'account',cart:'cart',checkout:'checkout',admin:'admin','admin-login':'adminLogin',book:'books'})[pageName]||'books');document.querySelectorAll('[data-i]').forEach(e=>e.innerHTML=t(e.dataset.i));document.querySelectorAll('[data-placeholder]').forEach(e=>e.placeholder=t(e.dataset.placeholder));$('#language').innerHTML=(lang==='uk'?'UA':'EN')+' <span>⌄</span>';$('#theme').textContent=theme==='light'?'☾':'☀';$('#theme').ariaLabel=t('theme');$('#account').ariaLabel=t('accountLabel');$('#cart').ariaLabel=t('cartLabel');$('#close-modal').ariaLabel=t('close');if($('#search'))$('#search').ariaLabel=t('search');if($('#sort')){const sort=$('#sort').value;$('#sort').ariaLabel=t('sortLabel');$('#sort').innerHTML=['popular','priceAsc','priceDesc','nameSort'].map(k=>`<option value="${k}">${t(k)}</option>`).join('');if(sort)$('#sort').value=sort}renderCategories();renderBooks()}
function renderCategories(){if(!$('#categories'))return;$('#categories').innerHTML=['all','fiction','nonfiction','classics','fantasy','children'].map(k=>`<button class="${category===k?'selected':''}" aria-pressed="${category===k}" data-category="${k}">${t(k)}</button>`).join('')}
function renderBooks(){if(!$('#books'))return;if(!books.length)return;const query=($('#search')?.value||'').toLocaleLowerCase().trim();let list=books.filter(b=>(category==='all'||b.category===category)&&[b.titleUk,b.titleEn,b.authorUk,b.authorEn,b.isbn].some(s=>s.toLocaleLowerCase().includes(query)));const sort=$('#sort')?.value;list.sort(sort==='priceAsc'?(a,b)=>a.price-b.price:sort==='priceDesc'?(a,b)=>b.price-a.price:sort==='nameSort'?(a,b)=>local(a,'title').localeCompare(local(b,'title'),lang):(a,b)=>Number(b.featured)-Number(a.featured));const total=list.length;if($('#result-count'))$('#result-count').textContent=t('found')+': '+total;if(pageName==='home')list=list.slice(0,4);else{currentPage=Math.min(currentPage,Math.max(1,Math.ceil(total/12)));list=list.slice((currentPage-1)*12,currentPage*12)}$('#books').innerHTML=list.length?list.map(cardHtml).join(''):`<div class="empty"><strong>${t('noBooks')}</strong>${t('trySearch')}<br><button class="link-button" data-action="reset">${t('reset')}</button></div>`;if($('#pagination')){const pages=Math.ceil(total/12);$('#pagination').innerHTML=pages>1?`<button data-page="${currentPage-1}" ${currentPage===1?'disabled':''}>← ${t('previous')}</button><span>${t('page')} ${currentPage} ${t('of')} ${pages}</span><button data-page="${currentPage+1}" ${currentPage===pages?'disabled':''}>${t('next')} →</button>`:''}}
async function loadBooks(){try{books=await api('/books');renderBooks()}catch(e){const target=$('#books')||$('#page-content');if(target)target.innerHTML=`<div class="error-panel">${t('unavailable')}<br><button class="button outline" data-action="retry">${t('retry')}</button></div>`}}
function addBook(id){const b=books.find(b=>b.id===id);if(!b)return;if((cart[id]||0)>=Math.min(20,b.stock)){toast(t('limit'));return}cart[id]=(cart[id]||0)+1;persist();toast(t('added'))}
function show(view,html,wide=false){modalView=view;if(['login','register','account','cart','checkout','admin','admin-login'].includes(pageName)&&$('#page-content')){$('#page-content').innerHTML=html;return}$('#modal').classList.toggle('wide',wide);$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
function close(){if($('#modal').open){$('#modal').close();modalView=null}else location.assign('/catalog/')}
function detail(id){const b=books.find(x=>x.id===id);if(b)location.assign('/book/?isbn='+encodeURIComponent(b.isbn))}
function cartLines(){return Object.entries(cart).map(([id,q])=>{const b=books.find(x=>x.id===id);return b?{b,q}:null}).filter(Boolean)}
function subtotal(){return cartLines().reduce((n,{b,q})=>n+b.price*q,0)}
function renderCart(){const lines=cartLines();show({name:'cart'},`<h2 class="modal-heading">${t('cart')}</h2>${!lines.length?`<div class="empty"><strong>${t('emptyCart')}</strong>${t('emptyCartBody')}</div><button class="button primary full" data-action="close">${t('continue')}</button>`:lines.map(({b,q})=>`<div class="cart-line"><img src="${esc(b.cover)}" alt="${esc(b.titleEn)}"><div><h3>${esc(local(b,'title'))}</h3><div class="quantity"><button data-qty="${b.id}" data-delta="-1" aria-label="−">−</button><span>${q}</span><button data-qty="${b.id}" data-delta="1" aria-label="+">+</button><button class="link-button" data-remove="${b.id}">${t('remove')}</button></div></div><span>${money(b.price*q)}</span></div>`).join('')+`<div class="total"><span>${t('total')}</span><strong>${money(subtotal())}</strong></div><p class="subtle">${t('delivery')}</p><button class="button primary full" data-action="checkout">${t('checkout')} ↗</button><p class="subtle">${t('previewPrices')}</p>`}`)}
function field(name,label,type='text',value='',extra=''){return `<label>${t(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`}
function renderAuth(mode=pageName==='register'?'register':'login',after='account'){authMode=mode;const next=new URLSearchParams(location.search).get('next');after=next==='/checkout/'?'checkout':'account';show({name:'auth',mode,after},`<h2 class="modal-heading">${t(mode==='login'?'welcome':'registration')}</h2><p class="subtle">${t('authBody')}</p><form id="auth-form">${mode==='register'?field('name','name','text','','minlength="2" maxlength="100" autocomplete="name"'):''}${field('email','email','email','','maxlength="254" autocomplete="email"')}${field('password','password','password','','minlength="'+(mode==='register'?12:1)+'" maxlength="128" autocomplete="'+(mode==='register'?'new-password':'current-password')+'"')}<span class="subtle">${mode==='register'?t('passwordHint'):''}</span><div class="form-error" role="alert"></div><button class="button primary" type="submit">${t(mode==='login'?'login':'register')}</button></form><p class="subtle">${t(mode==='login'?'goRegister':'goLogin')} <a class="text-link" href="/${mode==='login'?'register':'login'}/${after==='checkout'?'?next=/checkout/':''}">${t(mode==='login'?'register':'login')}</a></p>`)}
function orderHtml(o,admin=false){return `<article class="order"><div class="order-top"><strong>${t('orderNumber')} #${o.id.slice(0,8).toUpperCase()}</strong><span class="status status-${esc(o.status)}">${t(o.status)}</span></div><small>${new Date(o.createdAt).toLocaleString(lang==='uk'?'uk-UA':'en-GB')}</small><div class="order-items">${o.items.map(i=>`${esc(local(i,'title'))} × ${i.quantity} — ${money(i.price*i.quantity)}`).join('<br>')}</div><strong>${money(o.total)}</strong><p class="subtle">${esc(o.name)} · ${esc(o.phone)}<br>${o.deliveryMethod==='nova_poshta'?t('novaPoshta')+' · ':''}${esc(o.city)}, ${esc(o.address)}<br>${t('payment')}</p>${o.trackingNumber?`<div class="tracking-card"><span>${t('trackingNumber')}</span><strong>${esc(o.trackingNumber)}</strong><a class="text-link" href="https://novaposhta.ua/tracking/" target="_blank" rel="noopener noreferrer">${t('trackParcel')} ↗</a></div>`:''}${!admin&&['pending','confirmed'].includes(o.status)?`<button class="button outline" data-cancel-order="${o.id}">${t('cancelOrder')}</button>`:''}${admin&&['pending','confirmed','shipped'].includes(o.status)?`<div class="form-row"><select data-order-status="${o.id}" aria-label="${t('updateStatus')}">${[o.status,...(o.status==='pending'?['confirmed','cancelled']:o.status==='confirmed'?['cancelled']:['completed'])].map(s=>`<option value="${s}">${t(s)}</option>`).join('')}</select><button class="button outline" data-update-order="${o.id}">${t('updateStatus')}</button></div>`:''}${admin&&['confirmed','shipped'].includes(o.status)?`<form class="shipment-form" data-order-id="${o.id}"><label>${t('trackingNumber')}<input name="trackingNumber" value="${esc(o.trackingNumber||'')}" inputmode="numeric" pattern="[0-9]{14}" minlength="14" maxlength="14" required></label><p class="subtle">${t('trackingHint')}</p><div class="form-error" role="alert"></div><button class="button outline" type="submit">${t(o.status==='shipped'?'updateShipment':'saveShipment')}</button></form>`:''}</article>`}
async function renderAccount(){if(!user){location.assign('/login/');return}show({name:'account'},`<div class="account-welcome"><div><h2 class="modal-heading">${t('account')}</h2><p>${esc(user.name)}<br><span class="subtle">${esc(user.email)}</span></p></div><div>${user.role==='admin'?`<a class="button outline" href="/admin/">${t('admin')}</a>`:''}<button class="link-button" data-action="logout">${t('logout')}</button></div></div><h3>${t('myOrders')}</h3><div id="account-orders">${t('working')}</div>`);try{orders=await api('/orders');if(modalView?.name==='account')$('#account-orders').innerHTML=orders.length?orders.map(o=>orderHtml(o)).join(''):`<div class="empty"><strong>${t('noOrders')}</strong>${t('noOrdersBody')}<p><a class="button primary" href="/catalog/">${t('catalog')} ↗</a></p></div>`}catch(e){toast(e.message)}}
function renderCheckout(){if(!cartLines().length){location.assign('/cart/');return}if(!user){location.assign('/login/?next=/checkout/');return}show({name:'checkout'},`<a class="text-link" href="/cart/">← ${t('cart')}</a><h2 class="modal-heading">${t('checkout')}</h2><div class="checkout-layout"><form id="checkout-form">${field('name','name','text',checkoutDraft.name||user.name,'minlength="2" maxlength="100" autocomplete="name"')}${field('phone','phone','tel',checkoutDraft.phone||'','maxlength="25" autocomplete="tel" placeholder="+380501234567"')}<p class="subtle">${t('phoneHint')}</p><div class="shipping-heading"><span class="np-mark">↗</span><strong>${t('novaPoshta')}</strong></div><label>${t('shippingCity')}<input id="city-search" name="city" value="${esc(shipping.city?.name||checkoutDraft.city||'')}" required minlength="2" maxlength="100" autocomplete="off" aria-controls="city-results" placeholder="${t('shippingCityHint')}"></label><div id="city-results" class="shipping-results" aria-live="polite">${shipping.city?`<span class="badge">✓ ${esc(shipping.city.name)} ${esc(shipping.city.region||'')}</span>`:`<span class="subtle">${t('chooseCity')}</span>`}</div><input type="hidden" name="cityRef" value="${esc(shipping.city?.ref||'')}"><label>${t('warehouseSearch')}<input id="warehouse-search" type="search" value="${esc(shipping.query)}" maxlength="100" ${!shipping.city?'disabled':''} placeholder="${t('warehouseSearch')}"></label><label>${t('warehouse')}<select name="warehouseRef" id="warehouse-select" required ${!shipping.city?'disabled':''}></select></label><div id="warehouse-status" aria-live="polite"></div><button id="more-warehouses" class="link-button" data-action="more-warehouses" type="button" hidden>${t('moreWarehouses')} ↓</button><p class="subtle">${t('warehouseHint')}</p><div id="destination-summary"></div><input type="hidden" name="address" value="${esc(shipping.selected?.name||'')}"><input type="hidden" name="deliveryMethod" value="nova_poshta"><p class="subtle">${t('shippingLive')}</p><div><strong>${t('payment')}</strong><p class="subtle">${t('paymentBody')}</p><p class="subtle">${t('deliveryTariff')}</p></div><div class="form-error" role="alert"></div><button class="button primary" type="submit" ${!shipping.selected?'disabled':''}>${t('placeOrder')}</button></form><aside class="checkout-summary"><h3>${t('cart')}</h3>${cartLines().map(({b,q})=>`<div class="checkout-book"><img src="${esc(b.cover)}" alt="${esc(b.titleEn)}"><div>${esc(local(b,'title'))}<small>× ${q}</small></div><strong>${money(b.price*q)}</strong></div>`).join('')}<div class="total"><span>${t('total')}</span><strong>${money(subtotal())}</strong></div><p class="subtle">${t('delivery')}</p></aside></div>`);renderWarehouseOptions();renderDestination()}
async function renderAdmin(tab='books'){if(user?.role!=='admin'){location.assign('/admin/login/');return}show({name:'admin',tab},`<div class="account-welcome"><div><h2 class="modal-heading">${t('admin')}</h2><p class="subtle">${esc(user.name)} · ${esc(user.email)}</p></div><button class="link-button" data-action="admin-logout">${t('logout')}</button></div><div class="tabs"><button class="${tab==='books'?'selected':''}" data-admin-tab="books">${t('books')}</button><button class="${tab==='orders'?'selected':''}" data-admin-tab="orders">${t('orders')}</button><a class="text-link" href="/catalog/">${t('viewShop')} ↗</a></div><div id="admin-content">${t('working')}</div>`,true);try{[adminBooks,adminOrders]=await Promise.all([api('/admin/books'),api('/admin/orders')]);if(modalView?.name!=='admin')return;const total=adminOrders.filter(o=>o.status!=='cancelled').reduce((a,o)=>a+o.total,0);$('#admin-content').innerHTML=`<div class="admin-stats"><div><strong>${adminBooks.length}</strong>${t('books')}</div><div><strong>${adminOrders.length}</strong>${t('orders')}</div><div><strong>${money(total)}</strong>${t('revenue')}</div></div>`+(tab==='orders'?`<div class="admin-filters"><input id="admin-order-search" type="search" value="${esc(adminQuery)}" placeholder="${t('adminSearch')}" aria-label="${t('adminSearch')}"><select id="admin-status" aria-label="${t('orderTracking')}">${['all','pending','confirmed','shipped','completed','cancelled'].map(v=>`<option value="${v}" ${adminStatus===v?'selected':''}>${t(v==='all'?'allStatuses':v)}</option>`).join('')}</select></div><div id="admin-order-list"></div>`:`<button class="button primary" data-action="new-book">+ ${t('newBook')}</button><div class="table-scroll"><table class="admin-table"><thead><tr><th>${t('books')}</th><th>ISBN</th><th>${t('price')}</th><th>${t('stock')}</th><th></th></tr></thead><tbody>${adminBooks.map(b=>`<tr><td>${esc(local(b,'title'))}${!b.active?' · ○':''}</td><td>${esc(b.isbn)}</td><td>${money(b.price)}</td><td>${b.stock}</td><td><button class="link-button" data-edit-book="${b.id}">${t('edit')}</button></td></tr>`).join('')}</tbody></table></div>`);if(tab==='orders')renderAdminOrders()}catch(e){$('#admin-content').innerHTML=`<p role="alert">${esc(e.message)}</p><button class="button outline" data-admin-tab="${tab}">${t('retry')}</button>`}}
function renderAdminOrders(){const query=adminQuery.trim().toLocaleLowerCase();const list=adminOrders.filter(o=>(adminStatus==='all'||o.status===adminStatus)&&[o.id,o.name,o.phone,o.city,o.trackingNumber||''].some(v=>v.toLocaleLowerCase().includes(query)));$('#admin-order-list').innerHTML=list.length?list.map(o=>orderHtml(o,true)).join(''):`<div class="empty">${t('noMatchingOrders')}</div>`}
function renderAdminLogin(){if(user?.role==='admin'){location.assign('/admin/');return}show({name:'admin-login'},`<div class="admin-login-card"><div class="eyebrow">CHERRY BOOKS / ADMIN</div><h2 class="modal-heading">${t('adminLogin')}</h2><p class="subtle">${t('adminLoginBody')}</p><form id="admin-auth-form">${field('email','email','email','','maxlength="254" autocomplete="username"')}${field('password','password','password','','maxlength="128" autocomplete="current-password"')}<div class="form-error" role="alert"></div><button class="button primary full" type="submit">${t('login')} ↗</button></form><a class="text-link" href="/">← ${t('viewShop')}</a></div>`)}
function renderBookForm(id){const b=adminBooks.find(b=>b.id===id)||{titleUk:'',titleEn:'',authorUk:'',authorEn:'',descriptionUk:'',descriptionEn:'',isbn:'',price:0,stock:0,pages:100,language:'English',cover:'https://covers.openlibrary.org/b/isbn/',category:'fiction',active:true,featured:false};show({name:'bookForm',id},`<button class="link-button" data-action="admin">← ${t('back')}</button><h2 class="modal-heading">${t(id?'edit':'newBook')}</h2><form id="book-form" data-id="${id||''}"><div class="form-row">${field('titleUk','titleUk','text',b.titleUk,'maxlength="200"')}${field('titleEn','titleEn','text',b.titleEn,'maxlength="200"')}${field('authorUk','authorUk','text',b.authorUk,'maxlength="200"')}${field('authorEn','authorEn','text',b.authorEn,'maxlength="200"')}${field('isbn','ISBN','text',b.isbn,'pattern="[0-9]{10}|[0-9]{13}"')}${field('price','price','number',b.price/100,'min="0.01" max="100000" step="0.01"')}${field('stock','stock','number',b.stock,'min="0" max="100000" step="1"')}${field('pages','pageCount','number',b.pages,'min="1" max="9999" step="1"')}${field('language','language','text',b.language,'maxlength="50"')}<label>${t('category')}<select name="category">${['fiction','nonfiction','classics','fantasy','children'].map(c=>`<option value="${c}" ${b.category===c?'selected':''}>${t(c)}</option>`).join('')}</select></label></div>${field('cover','cover','text',b.cover)}<label>${t('descriptionUk')}<textarea name="descriptionUk" required maxlength="4000" rows="3">${esc(b.descriptionUk)}</textarea></label><label>${t('descriptionEn')}<textarea name="descriptionEn" required maxlength="4000" rows="3">${esc(b.descriptionEn)}</textarea></label><div><label class="admin-check"><input type="checkbox" name="active" ${b.active?'checked':''}>${t('active')}</label><label class="admin-check"><input type="checkbox" name="featured" ${b.featured?'checked':''}>${t('featuredCheck')}</label></div><div class="form-error" role="alert"></div><button type="submit" class="button primary">${t('save')}</button></form>`,true)}
function refreshModal(){if(pageName!=='home'&&pageName!=='catalog'&&pageName!=='about'&&pageName!=='contacts'&&pageName!=='delivery'&&pageName!=='faq'){routePage();return}const v=modalView;if(v?.name==='cart')renderCart()}
$('#language').onclick=()=>{if($('#checkout-form'))checkoutDraft=Object.fromEntries(new FormData($('#checkout-form')));lang=lang==='uk'?'en':'uk';localStorage.setItem('cherry-lang',JSON.stringify(lang));translate();refreshModal()};$('#theme').onclick=()=>{theme=theme==='light'?'dark':'light';localStorage.setItem('cherry-theme',JSON.stringify(theme));translate()};$('#account').onclick=()=>location.assign(user?'/account/':'/login/');$('#cart').onclick=()=>location.assign('/cart/');$('#close-modal').onclick=close;$('#modal').addEventListener('cancel',()=>modalView=null);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});if($('#editor-book'))$('#editor-book').onclick=()=>detail('b0000000-0000-0000-0000-000000000003');if($('#search'))$('#search').oninput=()=>{currentPage=1;renderBooks()};if($('#sort'))$('#sort').onchange=()=>{currentPage=1;renderBooks()};$('#mobile-menu').onclick=()=>{const nav=$('#mobile-nav');nav.hidden=!nav.hidden;$('#mobile-menu').ariaExpanded=String(!nav.hidden)};

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.category){currentPage=1;category=b.dataset.category;renderCategories();renderBooks()}
 if(b.dataset.page){currentPage=Number(b.dataset.page);renderBooks();document.querySelector('.page-heading')?.scrollIntoView();}if(b.dataset.npCity)await chooseCity(b.dataset.npCity);if(b.dataset.retryWarehouse)await fetchWarehouses(shipping.query,b.dataset.retryWarehouse==='more');if(b.dataset.cancelOrder){if(!confirm(t('cancelClientConfirm')))return;b.disabled=true;await api('/orders/'+b.dataset.cancelOrder+'/cancel','POST');toast(t('orderCancelled'));await loadBooks();await renderAccount();}if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.add)addBook(b.dataset.add);
 if(b.dataset.qty){const id=b.dataset.qty,book=books.find(x=>x.id===id),q=(cart[id]||0)+Number(b.dataset.delta);if(q>Math.min(20,book.stock)){toast(t('limit'));return}if(q<=0)delete cart[id];else cart[id]=q;persist();renderCart()}
 if(b.dataset.remove){delete cart[b.dataset.remove];persist();renderCart()}
 if(b.dataset.auth)renderAuth(b.dataset.auth,modalView?.after);
 if(b.dataset.adminTab)renderAdmin(b.dataset.adminTab);if(b.dataset.editBook)renderBookForm(b.dataset.editBook);
 if(b.dataset.updateOrder){const id=b.dataset.updateOrder,status=document.querySelector(`[data-order-status="${id}"]`).value,old=adminOrders.find(o=>o.id===id)?.status;if(status===old)return;if(status==='cancelled'&&!confirm(t('confirmCancel')))return;b.disabled=true;await api('/admin/orders/'+id,'PATCH',{status});toast(t('saved'));await loadBooks();await renderAdmin('orders')}
 switch(b.dataset.action){case 'more-warehouses':await fetchWarehouses(shipping.query,true);break;case 'retry-cities':await fetchCities($('#city-search').value.trim());break;case 'admin-logout':await api('/auth/logout','POST');user=null;location.assign('/admin/login/');break;case 'close':close();break;case 'reset':currentPage=1;category='all';if($('#search'))$('#search').value='';renderCategories();renderBooks();break;case 'retry':await loadBooks();break;case 'cart':location.assign('/cart/');break;case 'checkout':location.assign('/checkout/');break;case 'account':location.assign('/account/');break;case 'admin':location.assign('/admin/');break;case 'new-book':renderBookForm();break;case 'logout':await api('/auth/logout','POST');user=null;location.assign('/');break;}
 }catch(err){toast(err.message);b.disabled=false}});
document.addEventListener('submit',async e=>{if(!['auth-form','admin-auth-form','checkout-form','book-form'].includes(e.target.id)&&!e.target.matches('.shipment-form'))return;e.preventDefault();if(loading)return;const form=e.target,button=form.querySelector('[type=submit]'),error=form.querySelector('.form-error'),data=Object.fromEntries(new FormData(form));loading=true;button.disabled=true;const label=button.textContent;button.textContent=t('working');error.textContent='';try{
 if(form.id==='admin-auth-form'){const result=await api('/admin/login','POST',data);user=result.user;location.assign('/admin/')}
 if(form.matches('.shipment-form')){await api('/admin/orders/'+form.dataset.orderId+'/shipment','PATCH',data);toast(t('shipmentSaved'));await renderAdmin('orders')}
 if(form.id==='auth-form'){const after=modalView?.after;const result=await api('/auth/'+(authMode==='login'?'login':'register'),'POST',data);user=result.user;location.assign(after==='checkout'?'/checkout/':'/account/')}
 if(form.id==='checkout-form'){if(!shipping.city||!shipping.selected||shipping.selected.ref!==data.warehouseRef)throw new Error(t('invalid_shipping'));data.phone=data.phone.replace(/[\s()\-]/g,'');if(!/^(?:\+?380[0-9]{9}|0[0-9]{9})$/.test(data.phone))throw new Error(t('invalid_phone'));const order=await api('/orders','POST',{...data,items:cartLines().map(({b,q})=>({bookId:b.id,quantity:q}))});cart={};persist();await loadBooks();show({name:'success'},`<div class="success-symbol">♡</div><h2 class="modal-heading">${t('orderSuccess')}</h2><p>${t('orderSuccessBody')}</p><div class="order"><strong>#${order.id.slice(0,8).toUpperCase()}</strong><div class="total">${money(order.total)}</div><span class="status">${t('pending')}</span></div><br><button class="button primary full" data-action="account">${t('myOrders')}</button>`)}
 if(form.id==='book-form'){const id=form.dataset.id;await api('/admin/books'+(id?'/'+id:''),id?'PUT':'POST',{...data,...(id?{id}:{}),price:Math.round(Number(data.price)*100),stock:Number(data.stock),pages:Number(data.pages),featured:form.elements.featured.checked,active:form.elements.active.checked});toast(t('saved'));await loadBooks();await renderAdmin()}
 }catch(err){error.textContent=err.message;if(err.code==='out_of_stock')await loadBooks()}finally{loading=false;button.disabled=false;button.textContent=label}});


function cardHtml(b){const href='/book/?isbn='+encodeURIComponent(b.isbn);return `<article class="book-card"><a class="cover-stage" href="${href}" aria-label="${esc(local(b,'title'))}">${b.featured?`<span class="book-label">${t('featured')}</span>`:''}<img loading="lazy" src="${esc(b.cover)}" alt="${esc(b.titleEn+' — '+b.authorEn)}"></a><div class="book-info"><p class="book-author">${esc(local(b,'author'))}</p><a class="book-title" href="${href}">${esc(local(b,'title'))}</a><div class="book-language">${esc(b.language==='English'?t('english'):b.language)} · ${b.pages} ${t('pages')}</div><div class="book-bottom"><span class="price">${money(b.price)}</span><button class="add-book" data-add="${b.id}" aria-label="${t('add')}: ${esc(local(b,'title'))}" ${b.stock<1?'disabled':''}>+</button></div></div></article>`}
function renderBookPage(){const isbn=new URLSearchParams(location.search).get('isbn');const b=books.find(b=>b.isbn===isbn);if(!b){$('#page-content').innerHTML=`<div class="empty"><strong>${t('bookNotFound')}</strong><a class="button primary" href="/catalog/">${t('catalog')}</a></div>`;return}document.title=local(b,'title')+' — Cherry Books';$('#page-content').innerHTML=`<div class="breadcrumbs"><a href="/" >${t('home')}</a> / <a href="/catalog/">${t('catalog')}</a> / ${esc(local(b,'title'))}</div><div class="product-layout"><div class="product-cover"><img src="${esc(b.cover)}" alt="${esc(b.titleEn+' — '+b.authorEn)}"></div><div class="product-copy"><div class="eyebrow">${t(b.category)}</div><h1>${esc(local(b,'title'))}</h1><p class="product-author">${esc(local(b,'author'))}</p>${lang==='uk'?`<p class="subtle">${esc(b.titleEn)}</p>`:''}<p class="product-description">${esc(local(b,'description'))}</p><p class="badge">${b.stock>0?t('inStock')+': '+b.stock:t('outStock')}</p><div class="product-buy"><strong>${money(b.price)}</strong><button class="button primary" data-add="${b.id}" ${b.stock<1?'disabled':''}>${t('add')} +</button></div><p class="subtle">${t('previewPrices')}</p><div class="product-specs"><h3>${t('editionDetails')}</h3><div><span>ISBN</span><span>${esc(b.isbn)}</span></div><div><span>${t('pageCount')}</span><span>${b.pages}</span></div><div><span>${t('edition')}</span><span>${esc(b.language==='English'?t('languageEnglish'):b.language)}</span></div></div><a class="text-link" href="/delivery/">${t('novaPoshta')} · ${t('deliveryPage')} ↗</a></div></div><section class="related-books"><h2>${t('relatedBooks')}</h2><div class="book-grid">${books.filter(x=>x.id!==b.id).sort((a,z)=>Number(z.category===b.category)-Number(a.category===b.category)).slice(0,4).map(cardHtml).join('')}</div></section>`}
async function routePage(){if(pageName==='book')renderBookPage();else if(pageName==='login'||pageName==='register'){if(user){location.assign('/account/');return}renderAuth(pageName==='register'?'register':'login')}else if(pageName==='account')await renderAccount();else if(pageName==='cart')renderCart();else if(pageName==='checkout')renderCheckout();else if(pageName==='admin')await renderAdmin();else if(pageName==='admin-login')renderAdminLogin()}
async function chooseCity(ref){const city=shipping.cities.find(c=>c.ref===ref);if(!city)return;++cityRequest;++shippingRequest;shipping.city=city;shipping.selected=null;shipping.warehouses=[];shipping.page=0;shipping.query='';$('#city-search').value=city.name;$('#checkout-form').elements.cityRef.value=city.ref;$('#city-results').innerHTML=`<span class="badge">✓ ${esc(city.name)} ${esc(city.region||'')}</span>`;$('#warehouse-search').disabled=false;$('#warehouse-search').value='';renderDestination();await fetchWarehouses('')}
async function fetchWarehouses(query,append=false){const city=shipping.city;if(!city||!$('#checkout-form'))return;const request=++shippingRequest;const page=append?shipping.page+1:1;if(!append){shipping.query=query;shipping.selected=null;shipping.warehouses=[];shipping.page=0;renderDestination()}$('#warehouse-select').disabled=true;$('#more-warehouses').hidden=true;$('#warehouse-status').textContent=t('warehouseLoading');try{const result=await api('/shipping/nova-poshta/warehouses?cityRef='+encodeURIComponent(city.ref)+'&q='+encodeURIComponent(query)+'&page='+page);if(request!==shippingRequest||shipping.city?.ref!==city.ref||!$('#checkout-form'))return;shipping.warehouses=append?[...shipping.warehouses,...result.items.filter(w=>!shipping.warehouses.some(old=>old.ref===w.ref))]:result.items;shipping.page=result.page;shipping.hasMore=result.hasMore;renderWarehouseOptions();$('#warehouse-status').textContent=shipping.warehouses.length?'':t('noShippingResults')}catch(e){if(request!==shippingRequest||!$('#warehouse-status'))return;$('#warehouse-status').innerHTML=`<span class="form-error">${esc(e.message)}</span> <button type="button" class="link-button" data-retry-warehouse="${append?'more':'search'}">${t('retryShipping')}</button>`;$('#warehouse-select').disabled=!shipping.warehouses.length}}
function renderWarehouseOptions(){if(!$('#warehouse-select'))return;$('#warehouse-select').innerHTML=`<option value="">${t('chooseWarehouse')}</option>`+shipping.warehouses.map(w=>`<option value="${esc(w.ref)}" ${shipping.selected?.ref===w.ref?'selected':''}>${esc(w.name)}</option>`).join('');$('#warehouse-select').disabled=!shipping.warehouses.length;$('#more-warehouses').hidden=!shipping.hasMore}
function renderDestination(){if(!$('#checkout-form'))return;const place=shipping.selected;$('#checkout-form').elements.address.value=place?.name||'';$('#checkout-form').querySelector('[type=submit]').disabled=!place;$('#destination-summary').innerHTML=place?`<div class="destination-card"><span class="eyebrow">${t('selectedDestination')}</span><strong>${esc(shipping.city.name)}</strong><p>${esc(place.name)}</p>${place.address?`<p class="subtle">${esc(place.address)}</p>`:''}${place.schedule?`<details><summary>${t('openingHours')}</summary><div class="opening-hours">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].filter(day=>place.schedule[day]).map(day=>`<span>${t(day.slice(0,3))}</span><span>${esc(place.schedule[day])}</span>`).join('')}</div></details>`:''}</div>`:''}
let cityTimer,warehouseTimer;

document.addEventListener('input',e=>{if(e.target.id==='admin-order-search'){adminQuery=e.target.value;renderAdminOrders()}if(e.target.id==='city-search'){clearTimeout(cityTimer);clearTimeout(warehouseTimer);const request=++cityRequest;++shippingRequest;shipping.city=null;shipping.selected=null;shipping.warehouses=[];shipping.cities=[];shipping.hasMore=false;$('#checkout-form').elements.cityRef.value='';$('#warehouse-status').textContent='';$('#warehouse-search').value='';$('#warehouse-search').disabled=true;renderWarehouseOptions();renderDestination();const query=e.target.value.trim();if(query.length<2){$('#city-results').innerHTML=`<span class="subtle">${t('shippingCityHint')}</span>`;return}$('#city-results').textContent=t('working');cityTimer=setTimeout(()=>fetchCities(query,request),350)}if(e.target.id==='warehouse-search'){clearTimeout(warehouseTimer);++shippingRequest;shipping.selected=null;shipping.hasMore=false;shipping.warehouses=[];shipping.query=e.target.value.trim();renderWarehouseOptions();renderDestination();$('#warehouse-status').textContent=t('warehouseLoading');warehouseTimer=setTimeout(()=>fetchWarehouses(shipping.query),350)}});
async function fetchCities(query,request=++cityRequest){try{const list=await api('/shipping/nova-poshta/cities?q='+encodeURIComponent(query));if(request!==cityRequest||!$('#city-search')||$('#city-search').value.trim()!==query||shipping.city)return;shipping.cities=list;$('#city-results').innerHTML=list.length?list.map(c=>`<button type="button" data-np-city="${esc(c.ref)}"><strong>${esc(c.name)}</strong>${c.region?` <span class="subtle">${esc(c.region)}</span>`:''}</button>`).join(''):`<span class="subtle">${t('noShippingResults')}</span>`}catch(err){if(request===cityRequest&&$('#city-results'))$('#city-results').innerHTML=`<span class="form-error">${esc(err.message)}</span><button type="button" class="link-button" data-action="retry-cities">${t('retryShipping')}</button>`}}
document.addEventListener('change',e=>{if(e.target.id==='warehouse-select'){shipping.selected=shipping.warehouses.find(w=>w.ref===e.target.value)||null;renderDestination()}if(e.target.id==='admin-status'){adminStatus=e.target.value;renderAdminOrders()}});
async function initialize(){translate();persist();await Promise.all([loadBooks(),api('/auth/me').then(v=>user=v.user).catch(()=>{})]);await routePage()}
initialize();
